"""

from __future__ import annotations

import json
import os
from typing import Any
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen


API_URL = "https://api.openai.com/v1/responses"
DEFAULT_MODEL = "gpt-4.1-mini"


class OpenAIAPIError(RuntimeError):
    """An error occurred while contacting the Responses API."""


def send_prompt(
    prompt: str,
    *,
    model: str = DEFAULT_MODEL,
    instructions: str | None = None,
    timeout: float = 60.0,
) -> dict[str, Any]:
    """Send a text prompt and return the decoded Responses API object.

    The prompt and response are kept in memory only by this module. Neither is
    written to disk or included in raised error messages.
    """
    if not isinstance(prompt, str):
        raise TypeError("prompt must be a string")
    if not isinstance(model, str) or not model:
        raise ValueError("model must be a non-empty string")
    if timeout <= 0:
        raise ValueError("timeout must be greater than zero")

    api_key = [REDACTED_SECRET]"OPENAI_API_KEY")
    if not api_key:
        raise OpenAIAPIError("Set the OPENAI_API_KEY environment variable")

    payload: dict[str, Any] = {
        "model": model,
        "input": prompt,
        "store": False,
    }
    if instructions is not None:
        if not isinstance(instructions, str):
            raise TypeError("instructions must be a string or None")
        payload["instructions"] = instructions

    request = Request(
        API_URL,
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        },
        method="POST",
    )

    try:
        with urlopen(request, timeout=timeout) as response:
            result = json.loads(response.read().decode("utf-8"))
    except HTTPError as error:
        raise OpenAIAPIError(
            f"OpenAI Responses API returned HTTP {error.code}"
        ) from None
    except (URLError, TimeoutError, OSError):
        raise OpenAIAPIError("Could not connect to the OpenAI Responses API") from None
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise OpenAIAPIError("OpenAI Responses API returned invalid JSON") from None

    if not isinstance(result, dict):
        raise OpenAIAPIError("OpenAI Responses API returned an unexpected response")
    return result


def extract_text(response: dict[str, Any]) -> str:
    """Return generated text from a response returned by :func:`send_prompt`."""
    text = response.get("output_text")
    if isinstance(text, str):
        return text

    parts: list[str] = []
    for item in response.get("output", []):
        if not isinstance(item, dict):
            continue
        for content in item.get("content", []):
            if isinstance(content, dict) and content.get("type") == "output_text":
                value = content.get("text")
                if isinstance(value, str):
                    parts.append(value)
    return "".join(parts)
